})

Translate("frFR", "grayson-shadowbreaker", {
	title = "Grayson Shadowbreaker",
	subtitle = "Seigneur des paladins de la cathédrale",
	found = "La cathédrale de la Lumière, place de la Cathédrale",
	hint = [=[Cherchez le seigneur qui forme les paladins dans la cathédrale de la Lumière.]=],
	allegiance = "Église de la Lumière sacrée · Paladins de Stormwind",
	aliases = { "Seigneur Grayson Shadowbreaker", "Shadowbreaker" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le seigneur Grayson Shadowbreaker forme les paladins de {link:stormwind-city}Stormwind{/link} dans les salles de la cathédrale de la Lumière. C'est un chevalier et un maître, et ses élèves apprennent de lui que la {link:holy-light}Lumière sacrée{/link} demande le sacrifice avant d'accorder la force. Les jeunes paladins du royaume passent entre ses mains, et les anciens aussi, quand ils cherchent une voie plus rude.]=],
		},
		{
			title = "Importance",
			text = [=[{link:captain-grayson}Grayson{/link} maintient vivante l'union de la foi et de l'acier que l'Église de la {link:holy-light}Lumière sacrée{/link} forgea après la {link:first-war}Première Guerre{/link}. Ses conseils portent au-delà de {link:stormwind-city}Stormwind{/link}. Il envoie les jeunes paladins nains auprès de leurs propres maîtres à {link:ironforge}Ironforge{/link}, et on lui confie des objets saints que le royaume souhaite garder en sûreté.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il forme les paladins de la cathédrale.
• Il envoie les paladins nains auprès de Tiza Battleforge, à {link:ironforge}Ironforge{/link}.
• Il engage les paladins aguerris du royaume sur une longue route d'épreuves et de sacrifice.
• Il reçoit la statuette de Menethil pour qu'elle soit gardée dans la cathédrale.]=],
		},
		{
			title = "Non consigné",
			text = [=[On a peu écrit sur la vie de {link:captain-grayson}Grayson{/link} avant la cathédrale, ni sur les actes qui lui valurent son titre.]=],
		},
	},
	chapters = {
		{
			title = "Une relique de Terenas",
			hint = [=[Apportez à la cathédrale une petite statue de l'ancien roi de Lordaeron.]=],
			text = [=[Le roi {link:terenas-menethil}Terenas Menethil{/link} était un homme humble qui n'aimait pas les monuments, et peu de ses effigies survécurent à la chute de son royaume. Quand une petite statue de lui sortit des {link:wetlands}Paluns{/link}, la Lumière sembla reposer en elle. On la porta à {link:stormwind-city}Stormwind{/link} et on la confia au seigneur {link:captain-grayson}Grayson{/link}, pour qu'elle soit gardée dans la cathédrale de la Lumière.]=],
		},
		{
			title = "La route du sacrifice",
			hint = [=[Parcourez la longue route que le seigneur Grayson impose aux paladins du royaume.]=],
			text = [=[{link:captain-grayson}Grayson{/link} n'accorde pas à la légère les honneurs d'un paladin. La première épreuve qu'il impose est celle du sacrifice : un don coûteux à l'église d'{link:ironforge}Ironforge{/link}, en échange d'un encensoir sacré gardé par son grand prêtre.]=],
		},
	},
	mentions = {
		{ text = "Tome of Divinity" },
		{ text = "Emphasis on Sacrifice" },
		{ text = "Lord Grayson Shadowbreaker" },
		{ text = "A Friend of the Family" },
	},
	bonds = {
		{ id = "archbishop-benedictus", name = "Archevêque Benedictus", note = "dirige l'Église qu'il sert" },
		{ id = "bolvar-fordragon", name = "Bolvar Fordragon", note = "un autre champion de la Lumière" },
	},
})

